    # the main-text-end label attaches to the box's own paragraph (it followed a blank line, so when the box filled page 9 exactly the label
    # fell to page 10's first paragraph and the page census read 10 with the main text ending on page 9)
    E.append((BODY, "\\end{minipage}}\n\\end{center}\n\n\\label{main-text-end}\n", "\\end{minipage}}\\label{main-text-end}\n\\end{center}\n"))
    return E


