def groups():
    return {"block_a": block_a(), "block_a2": block_a2(), "block_b": block_b(), "block_c": block_c(), "block_d": block_d(), "block_e": block_e(), "block_f": block_f(), "block_f2": block_f2()}


def main():
    check = "--check" in sys.argv
    G = groups()
    names = sys.argv[sys.argv.index("--only") + 1].split(",") if "--only" in sys.argv else ["block_a"]
    edits = [e for g in names for e in G[g]]
    texts = apply(edits, check)
    if not check:
        for p, t in texts.items():
            io.open(p, "w", encoding="utf-8", newline="\n").write(t)
    print("r124_apply:", "check only" if check else "written", f"({len(edits)} edits, groups {names})")


if __name__ == "__main__":
    main()
